require __DIR__.'/../includes/bootstrap.php';require_login();$u=current_user();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Invalid bounty ID.');}$s=db()->prepare("SELECT * FROM bounties WHERE id=? AND status='open'");$s->execute([$id]);$b=$s->fetch();if(!$b){http_response_code(404);exit('Bounty not found or not open.');}if((int)$b['creator_id']===(int)$u['id']){http_response_code(403);exit('You cannot submit to your own bounty.');}
$errors=[];$url='';$notes='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$url=trim((string)($_POST['submission_url']??''));$notes=trim((string)($_POST['notes']??''));if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['https','http'],true))$errors[]='Enter a valid HTTP or HTTPS URL.';if(mb_strlen($notes)>5000)$errors[]='Notes must be 5,000 characters or fewer.';if(!$errors){$s=db()->prepare('SELECT id FROM submissions WHERE bounty_id=? AND contributor_id=?');$s->execute([$id,$u['id']]);if($s->fetch())$errors[]='You have already submitted work to this bounty.';else{$s=db()->prepare("INSERT INTO submissions(bounty_id,contributor_id,submission_url,notes,status) VALUES(?,?,?,?,'submitted')");$s->execute([$id,$u['id'],$url,$notes]);$sid=(int)db()->lastInsertId();audit((int)$u['id'],'submission_created','submission',$sid);flash('Work submitted successfully.','success');header('Location: /OpenBounty/bounties/view.php?id='.$id);exit;}}}
$pageTitle='Submit work';require __DIR__.'/../includes/header.php';
echo ob_page_head('Submit work', 'Share a pull request or evidence link for review.');
?><div class="ob-split rev"><aside class="ob-card glow"><span class="ob-skill">Bounty</span><h3 style="margin-top:10px"><a href="/OpenBounty/bounties/view.php?id=<?=(int)$b['id']?>" style="color:var(--text)"><?=e($b['title'])?></a></h3><div class="ob-reward" style="margin-top:8px"><?=e(xlm($b['reward_xlm']))?> <small>XLM</small></div><p class="ob-hint">Submitting does not trigger a payment. The creator reviews your work first.</p></aside>
<form method="post" class="ob-card"><?php if($errors): ?><div class="ob-flash error" role="alert"><ul><?php foreach($errors as $er): ?><li><?=e($er)?></li><?php endforeach; ?></ul></div><?php endif; ?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="ob-l" for="su" style="margin-top:0">Work URL (GitHub PR, repository, or evidence)</label><input class="ob-in" id="su" name="submission_url" type="url" required value="<?=e($url)?>" placeholder="https://github.com/.../pull/123"><label class="ob-l" for="sn">Notes (optional)</label><textarea class="ob-in" id="sn" name="notes" rows="5" maxlength="5000"><?=e($notes)?></textarea><div style="margin-top:18px"><button class="ob-btn" type="submit">Submit work</button> <a class="ob-btn ghost" href="/OpenBounty/bounties/view.php?id=<?=(int)$b['id']?>">Cancel</a></div></form></div>
